    pool: TAccountMetas[1];
    user: TAccountMetas[2];
    day: TAccountMetas[3];
    commitment: TAccountMetas[4];
    profile: TAccountMetas[5];
    /**
     * The global pool (crew_id 0) of the pool's mint, read live (audit CREW-1). Same account as
     * `pool` for a global-pool day.
     */
